/**
 * Shared helper for loading committed accessibility-tree baselines.
 * Baselines are generated by scripts/generate-a11y-baselines.js and stored in
 * tests/fixtures/accessibility-tree-baselines/.
 */

import { readFileSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const baselineDir = resolve(__dirname, '..', 'fixtures', 'accessibility-tree-baselines');

/**
 * Loads a baseline JSON file by name (e.g. 'accessibility-tree.json').
 * @param {string} name - Baseline file name
 * @returns {Array<{frame: number, elements: string[]}>} The baseline tree
 */
export function loadA11yBaseline(name) {
  return JSON.parse(readFileSync(resolve(baselineDir, name), 'utf-8'));
}
